def analyze_conversation(path_str, conv_id, label):
    p = Path(path_str)
    steps = []
    with open(p, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                try:
                    steps.append(json.loads(line))
                except Exception:
                    pass

    # Extract git commands, test outputs, PR creations, abort reasons
    git_commands = []
    tests_summary = []
    pr_actions = []
    aborted_reasons = []
    errors = []

    for s in steps:
        tcs = s.get("tool_calls") or []
        content = str(s.get("content") or "")

        for tc in tcs:
            fn = tc.get("name") or tc.get("function") or ""
            args = tc.get("arguments") or tc.get("args") or {}
            cmd = args.get("CommandLine", "") if isinstance(args, dict) else ""
            if "git " in cmd:
                git_commands.append(cmd)
            if "gh pr " in cmd:
                pr_actions.append(cmd)
            if "run_tests" in fn or "pio test" in cmd or "test_command" in cmd:
                pass

        if "FAILED" in content and "test cases:" in content:
            tests_summary.append("Test FAILED")
        elif "succeeded" in content and "test cases:" in content:
            m = re.search(r"(\d+)\s+test cases:\s+(\d+)\s+succeeded", content)
            if m:
                tests_summary.append(f"{m.group(1)} cases: {m.group(2)} succeeded")
            else:
                tests_summary.append("Tests passed")

        if "already has an open PR" in content or "already been resolved" in content or "PR already exists" in content or "already created" in content:
            aborted_reasons.append(content[:150])

        if "error" in s.get("status", "").lower():
            errors.append(str(s.get("content", ""))[:150])

    print(f"==================================================")
    print(f"[{conv_id}] {label}")
    print(f"Steps: {len(steps)}")
    print(f"PR actions: {pr_actions}")
    print(f"Tests summary: {tests_summary}")
    if aborted_reasons:
        print(f"Aborted / detected prior: {aborted_reasons[:2]}")
    # Print the last assistant response
    last_assistant = ""
    for s in reversed(steps):
        if s.get("source") == "MODEL" or s.get("type") == "PLANNER_RESPONSE":
            c = s.get("content", "")
            if c and isinstance(c, str):
                last_assistant = c
                break
    print(f"Outcome excerpt: {last_assistant[:300].strip()}\n")

for path, conv_id, label in transcript_paths:
    analyze_conversation(path, conv_id, label)

